/// Operand transforms of the results (`SDNodeXForm`).
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum XForm {
    /// `uint32_t enc = AArch64_AM::encodeAdvSIMDModImmType10(N->getValueAPF() .bitcastToAPInt() .getZExtValue()); return CurDAG->getTargetConstant(enc, SDLoc(N), MVT::i32);`
    Anonymous14228,
    /// `uint32_t enc = AArch64_AM::encodeAdvSIMDModImmType4(N->getValueAPF() .bitcastToAPInt() .getZExtValue()); return CurDAG->getTargetConstant(enc, SDLoc(N), MVT::i32);`
    Fpimm32SIMDModImmType4XForm,
    /// `uint32_t Enc = AArch64_AM::getFP32Imm(N->getValueAPF()); return CurDAG->getTargetConstant(Enc, SDLoc(N), MVT::i32);`
    Fpimm32XForm,
    /// `uint32_t Enc = AArch64_AM::getFP64Imm(N->getValueAPF()); return CurDAG->getTargetConstant(Enc, SDLoc(N), MVT::i32);`
    Fpimm64XForm,
    /// `uint64_t enc = (32 - N->getZExtValue()) & 0x1f; return CurDAG->getTargetConstant(enc, SDLoc(N), MVT::i64);`
    I32shiftA,
    /// `uint64_t enc = 31 - N->getZExtValue(); return CurDAG->getTargetConstant(enc, SDLoc(N), MVT::i64);`
    I32shiftB,
    /// `uint64_t enc = (64 - N->getZExtValue()) & 0x3f; return CurDAG->getTargetConstant(enc, SDLoc(N), MVT::i64);`
    I64shiftA,
    /// `uint64_t enc = 63 - N->getZExtValue(); return CurDAG->getTargetConstant(enc, SDLoc(N), MVT::i64);`
    I64shiftB,
    /// `uint64_t enc = 63 - N->getZExtValue(); enc = enc > 31 ? 31 : enc; return CurDAG->getTargetConstant(enc, SDLoc(N), MVT::i64);`
    I64shiftSextI32,
    /// `AArch64CC::CondCode CC = static_cast<AArch64CC::CondCode>(N->getZExtValue()); return CurDAG->getTargetConstant(AArch64CC::getInvertedCondCode(CC), SDLoc(N), MVT::i32);`
    InvCondXFORM,
    /// `uint64_t enc = AArch64_AM::encodeLogicalImmediate(N->getZExtValue(), 32); return CurDAG->getTargetConstant(enc, SDLoc(N), MVT::i32);`
    LogicalImm32XFORM,
    /// `uint64_t enc = AArch64_AM::encodeLogicalImmediate(N->getZExtValue(), 64); return CurDAG->getTargetConstant(enc, SDLoc(N), MVT::i32);`
    LogicalImm64XFORM,
}

