/// An instruction's encoding: the fixed bits and where each operand's bits go.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Encoding<'t> {
    pub bits: u32,
    pub fields: &'t [Field],
}

/// `width` bits of operand `operand`'s encoded value from bit `from`, at instruction bit `at`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Field {
    pub operand: u8,
    pub at: u8,
    pub from: u8,
    pub width: u8,
}

/// An instruction: its operands (outs, then ins), the pairs that must be one register, implicit registers, encoding.
#[derive(Clone, Copy, Debug)]
pub struct Desc<'t> {
    pub outs: u8,
    pub operands: &'t [MachineOperand<Class, Encoder>],
    pub tied: &'t [(u8, u8)],
    pub defs: &'t [Reg],
    pub uses: &'t [Reg],
    /// `None`: a pseudo instruction, expanded before encoding.
    pub encoding: Option<Encoding<'t>>,
}

